export const LOCALES = Object.freeze(['en', 'zh-Hant', 'zh-Hans', 'ja', 'ko', 'es', 'pt-BR', 'fr', 'de', 'it', 'ru', 'hi', 'ar']);
export const LOCALE_NAMES = Object.freeze(['English', '繁體中文', '简体中文', '日本語', '한국어', 'Español', 'Português', 'Français', 'Deutsch', 'Italiano', 'Русский', 'हिन्दी', 'العربية']);
const aliases = Object.freeze({ en: 'en', 'zh-hant': 'zh-Hant', 'zh-tw': 'zh-Hant', 'zh-hans': 'zh-Hans', 'zh-cn': 'zh-Hans', ja: 'ja', ko: 'ko', es: 'es', pt: 'pt-BR', 'pt-br': 'pt-BR', fr: 'fr', de: 'de', it: 'it', ru: 'ru', hi: 'hi', ar: 'ar' });
const localeOf = value => aliases[String(value || '').toLowerCase()] || null;

/** A locale route owns first paint; storage is optional and never a crash path. */
export function resolveLocale(options = {}) {
  const pathname = options.pathname ?? globalThis.location?.pathname ?? '';
  const parts = String(pathname).split('/').filter(Boolean);
  if (parts[0] === 'weightplay') parts.shift();
  const routed = localeOf(parts[0]);
  if (routed) return routed;
  try {
    const query = new URLSearchParams(options.search ?? globalThis.location?.search ?? '');
    const selected = localeOf(query.get('lang') || query.get('locale'));
    if (selected) return selected;
  } catch { /* Continue with current shared preference. */ }
  try {
    const storage = Object.prototype.hasOwnProperty.call(options, 'storage') ? options.storage : globalThis.localStorage;
    const selected = localeOf(storage?.getItem('weightPlayLocale'));
    if (selected) return selected;
  } catch { /* Browser storage can be unavailable. */ }
  return localeOf(options.documentLanguage ?? globalThis.document?.documentElement?.lang) || 'en';
}

