const dictionaries = Object.fromEntries(LOCALES.map(locale => [locale, Object.create(null)]));
for (const row of rows) {
  if (row.length !== LOCALES.length + 1) throw new Error(`Invalid Bramble Rapids locale row: ${row[0]}`);
  LOCALES.forEach((locale, index) => {
    if (typeof row[index + 1] !== 'string' || !row[index + 1].trim()) throw new Error(`Missing translation: ${locale}/${row[0]}`);
    dictionaries[locale][row[0]] = row[index + 1];
  });
}

export const CATALOGS = dictionaries;

export function t(locale, key, values = {}) {
  const selected = localeOf(locale);
  if (!selected || !Object.prototype.hasOwnProperty.call(dictionaries[selected], key)) throw new Error(`Missing Bramble Rapids translation: ${locale}/${key}`);
  return dictionaries[selected][key].replace(/\{(\w+)\}/g, (all, name) => Object.prototype.hasOwnProperty.call(values, name) ? String(values[name]) : all);
}

