export function guide(locale) {
  return {
    classification: 'general',
    title: t(locale, 'viewGuide'),
    goal: t(locale, 'guideGoal'),
    howToPlay: t(locale, 'summary'),
    controlsAndRules: `${t(locale, 'guideControls')} ${t(locale, 'guideRules')}`,
    finishingAndFeedback: t(locale, 'guideFinish'),
    strategy: t(locale, 'guideStrategy'),
    progression: t(locale, 'guideFreeBoards'),
    save: t(locale, 'guideSave'),
    faq: [
      { question: t(locale, 'faqJump'), answer: t(locale, 'tutorialJump') },
      { question: t(locale, 'faqFall'), answer: t(locale, 'guideRules') },
      { question: t(locale, 'faqBoards'), answer: t(locale, 'guideFreeBoards') },
      { question: t(locale, 'faqDiamonds'), answer: t(locale, 'guideNoPower') },
      { question: t(locale, 'faqSave'), answer: t(locale, 'guideSave') },
    ],
  };
}

