/** The controller and first-response renderer share these exact I9 related cards. */
export function renderRelatedGames(locale) {
  const selected = localeOf(locale);
  if (!selected) throw new Error(`BRAMBLE_RELATED_LOCALE_INVALID: ${locale}`);
  const cards = RELATED_GAMES.map(game => `<a class="game-info-related-card" data-game-id="${game.id}" href="/${ROUTE_SEGMENTS[selected]}/games/${game.id}/"><span class="game-info-related-poster"><img src="${game.poster}" data-final-src="/assets/weightplay-logo.png" alt="${htmlText(game.titles[selected])}" width="320" height="320" loading="lazy" decoding="async"></span><span class="game-info-related-copy"><strong data-runtime-localize="off">${htmlText(game.titles[selected])}</strong></span></a>`).join('');
  return `<div class="game-info-section game-info-related-section" data-wp-guide-related-interface="9"><h3>${htmlText(t(selected, 'relatedGamesTitle'))}</h3><div class="game-info-related">${cards}</div></div>`;
}

export function renderGameplayTags(locale) {
  return `<div class="game-info-tags" data-wp-gameplay-tags="1.4.0">${['tagRiverRacing', 'tagRampTiming'].map(key => `<span>${htmlText(t(locale, key))}</span>`).join('')}</div>`;
}
const routeAttribute = (tag, name) => tag.match(new RegExp(`(?:^|\\s)${name}\\s*=\\s*(["'])(.*?)\\1`, 'i'))?.[2];
const setRouteAttribute = (tag, name, value) => {
  const pattern = new RegExp(`\\s${name}\\s*=\\s*(["'])[\\s\\S]*?\\1`, 'i');
  const attribute = ` ${name}="${htmlText(value)}"`;
  return pattern.test(tag) ? tag.replace(pattern, attribute) : tag.replace(/>$/, `${attribute}>`);
};

function replaceRouteElement(html, id, replacement) {
  const opening = new RegExp(`<([a-z][\\w-]*)\\b(?=[^>]*\\bid=["']${id}["'])[^>]*>`, 'i').exec(html);
  if (!opening) throw new Error(`BRAMBLE_ROUTE_ELEMENT_MISSING: ${id}`);
  const tokens = new RegExp(`<\\/?${opening[1]}\\b[^>]*>`, 'gi');
  tokens.lastIndex = opening.index;
  let depth = 0, token;
  while ((token = tokens.exec(html))) {
    depth += /^<\//.test(token[0]) ? -1 : /\/>$/.test(token[0]) ? 0 : 1;
    if (depth === 0) return html.slice(0, opening.index) + replacement + html.slice(tokens.lastIndex);
  }
  throw new Error(`BRAMBLE_ROUTE_ELEMENT_UNCLOSED: ${id}`);
}

/** Pure first-response renderer used only by the canonical localized-route writer. */
export function renderLocalizedRoute(sourceHtml, locale, titles) {
  const selected = localeOf(locale);
  if (!selected || typeof sourceHtml !== 'string' || !/data-game-id=["']bramble-rapids["']/.test(sourceHtml)) throw new Error('BRAMBLE_ROUTE_SOURCE_INVALID');
  for (const required of LOCALES) {
    if (typeof titles?.[required] !== 'string' || !titles[required].trim()) throw new Error(`BRAMBLE_ROUTE_OFFICIAL_TITLE_MISSING: ${required}`);
  }
  const title = titles[selected].trim(), pageTitle = `${title} | WeightPlay`, segment = ROUTE_SEGMENTS[selected];
  const route = `https://weightplay.com/${segment}/games/bramble-rapids/`;
  const description = t(selected, 'pageDescription'), content = guide(selected);
  let html = sourceHtml.replace(/<html\b[^>]*>/i, opening => setRouteAttribute(setRouteAttribute(opening, 'lang', selected), 'dir', selected === 'ar' ? 'rtl' : 'ltr'));
  html = html.replace(/<body\b[^>]*>/i, opening => setRouteAttribute(opening, 'data-audience', 'general'));
  html = html.replace(/(<([a-z][\w-]*)\b[^>]*\bdata-t=["']([^"']+)["'][^>]*>)[\s\S]*?(<\/\2\s*>)/gi, (_all, open, _tag, key, close) => `${open}${htmlText(t(selected, key, { cost: routeAttribute(open, 'data-cost') || 5 }))}${close}`);
  html = html.replace(/<[a-z][\w-]*\b[^>]*\bdata-t-aria=["'][^"']+["'][^>]*>/gi, opening => setRouteAttribute(opening, 'aria-label', t(selected, routeAttribute(opening, 'data-t-aria'))));
  html = html.replace(/(<([a-z][\w-]*)\b[^>]*\bdata-wp-game-title(?=[\s=>])[^>]*>)[\s\S]*?(<\/\2\s*>)/gi, (_all, open, _tag, close) => `${open}${htmlText(title)}${close}`);
  html = replaceRouteElement(html, 'mainProgress', `<p id="mainProgress" data-wp-main-progress data-wp-frame-progress>${htmlText(t(selected, 'stage'))} 1 / 60</p>`);
  html = html.replace(/<a\b(?=[^>]*\bid=["']mainBack["'])[^>]*>/i, opening => setRouteAttribute(setRouteAttribute(opening, 'href', `/${segment}/`), 'aria-label', t(selected, 'backLobby')));
  html = html.replace(/<img\b(?=[^>]*\bid=["']poster["'])[^>]*>/i, opening => setRouteAttribute(opening, 'alt', t(selected, 'posterAlt')));
  html = html.replace(/<[a-z][\w-]*\b(?=[^>]*\bid=["']riverArena["'])[^>]*>/i, opening => setRouteAttribute(opening, 'aria-label', t(selected, 'summary')));
  html = html.replace(/<nav\b(?=[^>]*\bid=["']stageTabs["'])[^>]*>/i, opening => setRouteAttribute(opening, 'aria-label', t(selected, 'stages')));

  const sections = [
    ['guideGoalTitle', content.goal], ['guideHowTitle', content.howToPlay],
    ['guideRulesTitle', content.controlsAndRules], ['guideFinishTitle', content.finishingAndFeedback],
    ['guideStrategyTitle', content.strategy], ['guideProgressionTitle', content.progression], ['guideSaveTitle', content.save],
  ].map(([heading, copy]) => `<section><h3>${htmlText(t(selected, heading))}</h3><p>${htmlText(copy)}</p></section>`).join('');
  const faq = content.faq.map(item => `<details><summary>${htmlText(item.question)}</summary><p>${htmlText(item.answer)}</p></details>`).join('');
  const facts = [`60 ${t(selected, 'stages')}`, `3 ${t(selected, 'boards')}`, t(selected, 'localRivals')].map(fact => `<span>${htmlText(fact)}</span>`).join('');
  const staticGuide = `<section id="gameGuide" class="game-page-info game-page-info-static" data-wp-game-guide data-wp-guide-locale="${selected}" aria-label="${htmlText(content.title)}"><div id="gameGuideTitle" class="game-info-hero" data-wp-content-slot="guide-title"><h2>${htmlText(title)} · ${htmlText(content.title)}</h2><p>${htmlText(description)}</p>${renderGameplayTags(selected)}</div><div id="gameGuideFacts" class="game-info-facts" data-wp-content-slot="guide-facts">${facts}</div><div id="gameGuideSections" class="game-info-sections" data-wp-content-slot="guide-sections">${sections}</div><div id="gameGuideFaq" data-wp-content-slot="guide-faq"><h3>${htmlText(t(selected, 'guideFaqTitle'))}</h3>${faq}</div><div id="gameGuideRelated" data-wp-content-slot="guide-related">${renderRelatedGames(selected)}</div></section>`;
  html = replaceRouteElement(html, 'gameGuide', staticGuide);

  // Route shells share the root game's actual files; no JS/CSS copies are made.
  const assetPath = value => {
    if (!value || /^(?:[a-z][\w+.-]*:|\/\/|#)/i.test(value)) return value;
    const resolved = new URL(value, 'https://weightplay.com/games/bramble-rapids/');
    return `../../../${resolved.pathname.slice(1)}${resolved.search}${resolved.hash}`;
  };
  html = html.replace(/\b(src|href)=(['"])([^'"]+)\2/gi, (whole, attribute, quote, value) => {
    if (attribute.toLowerCase() === 'href' && !/\.(?:css|js|mjs)(?:[?#]|$)/i.test(value)) return whole;
    return `${attribute}=${quote}${htmlText(assetPath(value))}${quote}`;
  });
  html = html.replace(/url\((['"]?)([^)'"\s]+)\1\)/gi, (_all, quote, value) => `url(${quote}${assetPath(value)}${quote})`);
  html = html.replace(/<title\b[^>]*>[\s\S]*?<\/title>/gi, '')
    .replace(/<link\b(?=[^>]*\brel=["'](?:canonical|alternate)["'])[^>]*>/gi, '')
    .replace(/<meta\b(?=[^>]*(?:\bname=["'](?:description|robots|twitter:[^"']+)["']|\bproperty=["']og:[^"']+["']))[^>]*>/gi, '')
    .replace(/<script\b[^>]*type=["']application\/ld\+json["'][^>]*>[\s\S]*?<\/script>/gi, '');
  html = html.replace(/<head\b[^>]*>[\s\S]*?(?=<\/head>)/i, head => head.replace(/^[\t ]+$/gm, '').replace(/\n{3,}/g, '\n\n'));
  const alternates = LOCALES.map(language => `<link rel="alternate" hreflang="${language}" href="https://weightplay.com/${ROUTE_SEGMENTS[language]}/games/bramble-rapids/">`).join('\n');
  const graph = {
    '@context': 'https://schema.org', '@graph': [
      { '@type': 'WebPage', '@id': route, url: route, name: pageTitle, description, inLanguage: selected, mainEntity: { '@id': `${route}#game` } },
      { '@type': 'VideoGame', '@id': `${route}#game`, name: title, description, url: route, image: 'https://weightplay.com/games/bramble-rapids/assets/cover.webp', inLanguage: selected, applicationCategory: 'GameApplication', gamePlatform: 'Web browser', isAccessibleForFree: true, mainEntityOfPage: { '@id': route } },
      { '@type': 'FAQPage', '@id': `${route}#faq`, inLanguage: selected, mainEntity: content.faq.map(item => ({ '@type': 'Question', name: item.question, acceptedAnswer: { '@type': 'Answer', text: item.answer } })) },
    ],
  };
  const metadata = `<title>${htmlText(pageTitle)}</title>\n<meta name="description" content="${htmlText(description)}">\n<meta name="robots" content="noindex,nofollow">\n<link rel="canonical" href="${route}">\n${alternates}\n<link rel="alternate" hreflang="x-default" href="https://weightplay.com/games/bramble-rapids/">\n<meta property="og:type" content="website"><meta property="og:site_name" content="WeightPlay"><meta property="og:title" content="${htmlText(pageTitle)}"><meta property="og:description" content="${htmlText(description)}"><meta property="og:url" content="${route}"><meta property="og:image" content="https://weightplay.com/games/bramble-rapids/assets/cover.webp"><meta property="og:image:alt" content="${htmlText(t(selected, 'posterAlt'))}">\n<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${htmlText(pageTitle)}"><meta name="twitter:description" content="${htmlText(description)}"><meta name="twitter:image" content="https://weightplay.com/games/bramble-rapids/assets/cover.webp">\n<script type="application/ld+json">${JSON.stringify(graph).replaceAll('<', '\\u003c')}</script>\n`;
  if (!/<\/head>/i.test(html)) throw new Error('BRAMBLE_ROUTE_HEAD_MISSING');
  return html.replace(/<\/head>/i, `${metadata}</head>`);
}
